//! The layout gate: the reference's own visitor stream, through this port's layout, must equal
//! the reference's text — byte for byte, for every fixture document.
//!
//! `tests/fixtures/legal_pdf/oracle.json` is generated by `parity/tools/gen_legal_pdf_fixtures.py`
//! from the pinned archive: for each PDF it records the callbacks pypdf handed to
//! `pdf_text.py` (per page: text, cm, tm, font size) and the text that module produced. Feeding
//! the recorded stream to [`mcp_server_rs::pdf`] isolates the layout from the parser: a failure
//! here is the algorithm, a pass there is not the parser.

use std::fs;

use serde_json::Value;

use mcp_server_rs::pdf::{VisitorCall, document_text, page_text};

fn oracle() -> Value {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/fixtures/legal_pdf/oracle.json"
    );
    serde_json::from_str(&fs::read_to_string(path).expect("fixture oracle")).expect("oracle json")
}

fn calls(page: &Value) -> Vec<VisitorCall> {
    let visitors = page.as_array().expect("a page's visitors");
    visitors
        .iter()
        .map(|call| VisitorCall {
            text: call["text"].as_str().expect("text").to_owned(),
            cm: matrix(&call["cm"]),
            tm: matrix(&call["tm"]),
            size: call["size"].as_f64().expect("size"),
        })
        .collect()
}

fn matrix(value: &Value) -> [f64; 6] {
    let numbers: Vec<f64> = value
        .as_array()
        .expect("a matrix")
        .iter()
        .map(|number| number.as_f64().expect("a number"))
        .collect();
    numbers.try_into().expect("six numbers")
}

#[test]
fn every_fixture_renders_the_reference_text_byte_for_byte() {
    let oracle = oracle();
    let pdfs = oracle["pdfs"].as_object().expect("the fixture documents");
    assert!(!pdfs.is_empty(), "the fixture set is not empty");
    for (name, entry) in pdfs {
        let visitors = entry["visitors"].as_array().expect("pages");
        let pages: Vec<String> = visitors
            .iter()
            .map(|page| page_text(&calls(page)))
            .collect();
        let rendered = document_text(&pages, pages.len());
        assert_eq!(
            rendered,
            entry["text"].as_str().expect("the oracle text"),
            "{name}"
        );

        if let Some(capped) = entry["text_max2"].as_str() {
            let read = document_text(&pages[..2], pages.len());
            assert_eq!(read, capped, "{name} (page cap)");
        }
    }
}
